<?php
declare(strict_types=1);
require_once __DIR__ . '/../repositories/commercial_repository.php';
function commercial_active_rules(mysqli $conn,int $restaurantId,int $customerId,DateTimeImmutable $at):array{$clock=$at->format('Y-m-d H:i:s');$maintenance=commercial_repository_one($conn,"SELECT setting_value,version FROM platform_settings WHERE setting_key='maintenance_mode' LIMIT 1");$restaurant=commercial_repository_one($conn,'SELECT city FROM restaurants WHERE id=?','i',[$restaurantId]);$city=(string)($restaurant['city']??'');$areas=commercial_repository_rows($conn,"SELECT id,name,city,radius_km,status,minimum_order,version FROM service_areas WHERE city=? ORDER BY id ASC",'s',[$city]);$fee=commercial_repository_one($conn,"SELECT id,rule_type,name,amount,unit,effective_at,status,version FROM fee_rules WHERE status='active' AND effective_at<=? ORDER BY effective_at DESC,id DESC LIMIT 1",'s',[$clock]);return['clock'=>$clock,'maintenanceMode'=>in_array(strtolower((string)($maintenance['setting_value']??'0')),['1','true','on','yes'],true),'maintenanceVersion'=>(int)($maintenance['version']??0),'serviceAreas'=>$areas,'serviceArea'=>array_values(array_filter($areas,static fn(array $row):bool=>(string)$row['status']==='active'))[0]??null,'feeRule'=>$fee===[]?null:$fee,'feeRuleVersion'=>(int)($fee['version']??0)];}
function commercial_service_area_for_city(mysqli $conn,string $city):array{return commercial_repository_one($conn,"SELECT id,name,city,radius_km,status,minimum_order,version FROM service_areas WHERE city=? AND status='active' ORDER BY id ASC LIMIT 1",'s',[$city]);}
function commercial_promotion_rules(mysqli $conn,string $code,DateTimeImmutable $at):array{$row=commercial_repository_one($conn,'SELECT id,code,audience,discount_type,discount_value,maximum_discount,minimum_order,usage_cap,budget,used_amount,starts_at,ends_at,status,scope,version FROM promotions WHERE code=? LIMIT 1','s',[$code]);if($row===[])return[];$time=$at->getTimestamp();return(strtotime((string)$row['starts_at'])<=$time&&strtotime((string)$row['ends_at'])>=$time&&(string)$row['status']==='active')?$row:[];}
